#include<immintrin.h>
class AvxHammingDS {
public:

    AvxHammingDS(const vector<string>& seqs)
        : n_(seqs.size()), m_(seqs.empty() ? 0 : seqs[0].size()) {

        for (auto& s : seqs) {
            assert(s.size() == m_);
        }

        stride_ = ((m_ + 31) / 32) * 32;
        data_ = (uint8_t*)aligned_alloc(32, n_ * stride_);

        for (size_t i = 0; i < n_; ++i) {
            const auto& s = seqs[i];
            uint8_t* row = data_ + i * stride_;
            memcpy(row, s.data(), m_);

            memset(row + m_, 0, stride_ - m_);
        }
    }

    ~AvxHammingDS() {
        free(data_);
    }

    size_t distance(size_t i, size_t j) const {
        assert(i < n_ && j < n_);
        const uint8_t* a = data_ + i * stride_;
        const uint8_t* b = data_ + j * stride_;
        size_t mismatches = 0;
        size_t blocks = stride_ / 32;  

        for (size_t k = 0; k < blocks; ++k) {
            __m256i va = _mm256_load_si256((const __m256i*)(a + k * 32));
            __m256i vb = _mm256_load_si256((const __m256i*)(b + k * 32));

            __m256i cmp = _mm256_cmpeq_epi8(va, vb);

            uint32_t eq_mask = _mm256_movemask_epi8(cmp);

            mismatches += __builtin_popcount(~eq_mask);
        }
        return mismatches;
    }

private:
    size_t n_, m_, stride_;
    uint8_t* data_;
};
int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<string> a;
    for(int i = 1; i <= n; i++) {
        string s;
        cin >> s;
        a.push_back(s);
    }
    AvxHammingDS search(a);
    for(int i = 1; i <= n; i++) {
        bool satis = true;
        for(int j = 1; j <= n; j++) {
            if(i != j) {
                debug(i, j);
                if(search.distance(i - 1, j - 1) != k) {
                    satis = false;
                    break;
                }
            }
        }
        if(satis) {
            cout << i;
            return 0;
        }
    }
}